/* ---------- app only: splash screen (OVERLIGHT + studio logo), ~2 s, while the game and the consent get ready ---------- */
const SPLASH = (() => {
  const img = new Image(); img.src = 'data:image/png;base64,';
  const t0 = performance.now(), DUR = 2000, FADE = 400;
  let done = false;
  return {
    on() {
      if (done) return false;
      if (bootReady && performance.now() - t0 >= DUR) { done = true; window.__splashDone = true; return false; }
      return true;
    },
    draw() {
      const t = performance.now() - t0, a = Math.min(1, t / FADE) * (bootReady ? Math.min(1, Math.max(0, (DUR - t) / FADE + 0.0001)) : 1);
      dim(1);
      const ts = Math.min(VW * 0.85 / 9.6, RS * 1.8 / 9.6, VH * 0.11, 88), y1 = CY - ts * 0.4;
      const w1 = textW('OVER', ts, 0.12), wsp = ts * 0.42, w2 = textW('LIGHT', ts, 0.12), x0 = CX - (w1 + wsp + w2) / 2;
      vtext('OVER', x0, y1, ts, C.cyan, { align: 'left', track: 0.12, weight: 0.09, alpha: a });
      vtext('LIGHT', x0 + w1 + wsp, y1, ts, C.mag, { align: 'left', track: 0.12, weight: 0.09, alpha: a });
      if (img.complete && img.naturalWidth) {
        const w = Math.min(VW * 0.42, VH * 0.5, 360), h = w * img.naturalHeight / img.naturalWidth;
        ctx.save(); ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = a * 0.95;
        ctx.drawImage(img, CX - w / 2, VH - safe.b - h - FS * 0.8, w, h);
        ctx.restore();
      }
    }
  };
})();

